 void SyncStudio(){if(studio==null||studioSync)return;studioSync=true;try{UpdateWindowTitle();foreach(ToolStripItem item in exportMenu.Items)item.Enabled=pdf.Enabled;printPrimary.Enabled=pdf.Enabled;int index=preview.SelectedIndex;if(textEditBefore!=null&&textEditIndex!=index)FinishTextEditing(true);SyncElementList();
  SyncRotation();bool locked=elementMetadata.Exists(m=>m.Index==index&&m.Locked);textInspector.Enabled=!locked;foreach(DataGridViewRow row in grid.Rows)row.ReadOnly=elementMetadata.Exists(m=>m.Index==row.Index&&m.Locked);bool mainLocked=elementMetadata.Exists(m=>m.Index==-1&&m.Locked);codeInspector.Enabled=!mainLocked;centerBarcode.Enabled=!mainLocked&&!hideBarcode;centerBarcode.Visible=index==-1;if(ShowSelectionInspector())return;bool isCode=index==-1||index==-2;codeInspector.Visible=isCode;textInspector.Visible=!isCode;if(isCode)return;var el=preview.Element(index);if(el==null)return;bool text=index>=0;UpdateUnitLabels(textInspector);selectionTitle.Text=text?Loc.T("Text"):symbols[-3-index].Name;InspectorVisible(inspectText,text);InspectorVisible(inspectFont,text);InspectorVisible(inspectNumbers[4],text);inspectBold.Visible=inspectCenter.Visible=inspectAutoWidth.Visible=text;inspectNumbers[4].Enabled=text;
  double[] values={el.X/unitFactor,el.Y/unitFactor,el.Width/unitFactor,el.Height/unitFactor,el.Font};for(int i=0;i<5;i++){inspectNumbers[i].Minimum=i<2?-500/(decimal)unitFactor:i==4?4:1/(decimal)unitFactor;inspectNumbers[i].Maximum=i==4?144:500/(decimal)unitFactor;if(!inspectNumbers[i].ContainsFocus)inspectNumbers[i].Value=Math.Max(inspectNumbers[i].Minimum,Math.Min(inspectNumbers[i].Maximum,(decimal)values[i]));}
  if(text){var row=grid.Rows[index];if(!inspectText.ContainsFocus||inspectedTextIndex!=index)inspectText.Text=Convert.ToString(row.Cells[0].Value);if(!inspectFont.Items.Contains(row.Cells[8].Value))inspectFont.Items.Add(row.Cells[8].Value);inspectFont.SelectedItem=row.Cells[8].Value;inspectBold.Checked=Convert.ToBoolean(row.Cells[6].Value);inspectCenter.Checked=Convert.ToBoolean(row.Cells[7].Value);inspectAutoWidth.Checked=Convert.ToBoolean(row.Cells[9].Value??false);inspectedTextIndex=index;}
 }finally{studioSync=false;}}
 void InspectorVisible(Control c,bool visible){c.Visible=visible;var label=textInspector.GetControlFromPosition(0,textInspector.GetRow(c)-1);if(label is Label)label.Visible=visible;}
 void CommitInspector(){if(studioSync||loading||preview.Selection.Count!=1||elementMetadata.Exists(m=>m.Index==preview.SelectedIndex&&m.Locked))return;int index=preview.SelectedIndex;if(index>=0&&index<grid.Rows.Count){loading=true;try{var r=grid.Rows[index];r.Cells[0].Value=inspectText.Text;for(int i=0;i<5;i++)r.Cells[i+1].Value=(double)inspectNumbers[i].Value;r.Cells[6].Value=inspectBold.Checked;r.Cells[7].Value=inspectCenter.Checked;r.Cells[9].Value=inspectAutoWidth.Checked;if(inspectFont.SelectedItem!=null)r.Cells[8].Value=inspectFont.SelectedItem;}finally{loading=false;}StoreAutoGeometry(index);Changed(this,EventArgs.Empty);}else if(index<=-3&&-3-index<symbols.Count){var symbol=symbols[-3-index];symbol.X=(double)inspectNumbers[0].Value*unitFactor;symbol.Y=(double)inspectNumbers[1].Value*unitFactor;symbol.Width=(double)inspectNumbers[2].Value*unitFactor;symbol.Height=(double)inspectNumbers[3].Value*unitFactor;if(symbol.Matrix!=null&&BarcodeCatalog.Square(symbol.Matrix.Type))symbol.Height=symbol.Width;Changed(this,EventArgs.Empty);}}
